// Money is always whole minor units (cents) in integers: KES 1,500.50 is 150050. Never a float.
import { cleanText, normalisePhone } from './validation.js';

export const PAYMENT_METHODS = Object.freeze(['mpesa', 'bank', 'cash', 'cheque', 'card', 'other']);
export const PAYMENT_METHOD_LABELS = Object.freeze({
  mpesa: 'M-Pesa', bank: 'Bank transfer', cash: 'Cash', cheque: 'Cheque', card: 'Card', other: 'Other',
});
export const PAYMENT_PURPOSES = Object.freeze(['tuition', 'application_fee', 'other']);
export const PAYMENT_PURPOSE_LABELS = Object.freeze({ tuition: 'Tuition', application_fee: 'Application fee', other: 'Other' });
export const CURRENCY = 'KES';
export const MAX_AMOUNT_MINOR = 10_000_000_000; // KES 100,000,000: anything above is a typo
export const EARLIEST_PAYMENT = Date.UTC(2000, 0, 1);

const EAT_OFFSET_MS = 3 * 3600 * 1000; // Kenya is UTC+3 all year, with no daylight saving
const MONTHS = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];
const REFERENCE_RE = /^[A-Z0-9][A-Z0-9 ._/#:-]{1,59}$/;

/**
 * Reads an amount such as 1500, "1,500.50", "KES 1 500" or "Ksh. 2,000" into integer cents.
 * Zero, negative, ambiguous ("1,5") and absurdly large values return null: they are not payments.
 * @returns {number|null}
 */
export function parseAmountMinor(raw) {
  if (typeof raw === 'number') {
    if (!Number.isFinite(raw) || raw <= 0) return null;
    const minor = Math.round(raw * 100);
    return minor >= 1 && minor <= MAX_AMOUNT_MINOR ? minor : null;
  }
  if (typeof raw !== 'string') return null;
  let text = raw.trim().replace(/^(?:kes|ksh|kshs|sh)\.?\s*/i, '').replace(/\s*(?:kes|ksh|kshs)\.?$/i, '').trim();
  if (!text || /[()-]/.test(text)) return null;
  if (/\s/.test(text)) {
    if (!/^\d{1,3}(?: \d{3})+(?:\.\d{1,2})?$/.test(text)) return null; // "1 500" yes, "15 00" no
    text = text.replace(/ /g, '');
  } else if (text.includes(',')) {
    if (!/^\d{1,3}(?:,\d{3})+(?:\.\d{1,2})?$/.test(text)) return null; // "1,500" yes, "1,5" no
    text = text.replace(/,/g, '');
  }
  if (!/^\d+(?:\.\d{1,2})?$/.test(text)) return null;
  const [whole, fraction = ''] = text.split('.');
  const minor = Number(whole) * 100 + Number(fraction.padEnd(2, '0'));
  return minor >= 1 && minor <= MAX_AMOUNT_MINOR ? minor : null;
}

/** 150050 becomes "KES 1,500.50"; whole shillings drop the decimals ("KES 1,500"). */
export function formatKes(minor) {
  const value = Number(minor);
  if (!Number.isFinite(value)) return '—';
  const sign = value < 0 ? '-' : '';
  const abs = Math.abs(Math.round(value));
  const whole = Math.floor(abs / 100).toLocaleString('en-KE');
  const cents = abs % 100;
  return `${sign}${CURRENCY} ${whole}${cents ? `.${String(cents).padStart(2, '0')}` : ''}`;
}

const pad = (n) => String(n).padStart(2, '0');

/** An Excel serial day count (1900 system) as wall-clock text, or null. */
export function excelSerialToText(serial) {
  if (typeof serial !== 'number' || !Number.isFinite(serial) || serial < 20000 || serial > 80000) return null;
  const ms = Math.round((serial - 25569) * 86400 * 1000);
  const d = new Date(ms);
  const date = `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;
  const time = `${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}:${pad(d.getUTCSeconds())}`;
  return time === '00:00:00' ? date : `${date} ${time}`;
}

function build(y, mo, d, h = 0, mi = 0, s = 0, offsetMs = EAT_OFFSET_MS) {
  if (mo < 1 || mo > 12 || d < 1 || d > 31 || h > 23 || mi > 59 || s > 59) return null;
  const probe = new Date(Date.UTC(y, mo - 1, d));
  if (probe.getUTCFullYear() !== y || probe.getUTCMonth() !== mo - 1 || probe.getUTCDate() !== d) return null;
  return new Date(Date.UTC(y, mo - 1, d, h, mi, s) - offsetMs);
}

function timeParts(text) {
  if (!text) return [0, 0, 0];
  const m = /^(\d{1,2}):(\d{2})(?::(\d{2}))?(?:\.\d+)?\s*([ap]m)?$/i.exec(text.trim());
  if (!m) return null;
  let h = Number(m[1]);
  const meridiem = m[4]?.toLowerCase();
  if (meridiem) {
    if (h < 1 || h > 12) return null;
    if (meridiem === 'pm' && h < 12) h += 12;
    if (meridiem === 'am' && h === 12) h = 0;
  }
  return [h, Number(m[2]), Number(m[3] ?? 0)];
}

/**
 * Reads the date formats that turn up in statements and spreadsheets. Dates are day-first (Kenya), and a
 * date without a time zone is Nairobi time. Returns a Date (an instant), or null when it cannot be read.
 */
export function parsePaidAt(raw) {
  if (raw instanceof Date) return Number.isNaN(raw.getTime()) ? null : raw;
  if (typeof raw === 'number') return parsePaidAt(excelSerialToText(raw));
  if (typeof raw !== 'string') return null;
  const text = raw.trim().replace(/\s+/g, ' ');
  if (!text) return null;

  let m = /^(\d{4})-(\d{2})-(\d{2})(?:[ T](\d{1,2}:\d{2}(?::\d{2})?(?:\.\d+)?))?\s*(Z|[+-]\d{2}:?\d{2})?$/i.exec(text);
  if (m) {
    const t = timeParts(m[4]);
    if (!t) return null;
    let offset = EAT_OFFSET_MS;
    if (m[5]) {
      if (m[5].toUpperCase() === 'Z') offset = 0;
      else {
        const sign = m[5][0] === '-' ? -1 : 1;
        const digits = m[5].slice(1).replace(':', '');
        offset = sign * (Number(digits.slice(0, 2)) * 60 + Number(digits.slice(2))) * 60000;
      }
    }
    return build(Number(m[1]), Number(m[2]), Number(m[3]), ...t, offset);
  }

  m = /^(\d{1,2})[/.-](\d{1,2})[/.-](\d{2}|\d{4})(?: (.+))?$/.exec(text);
  if (m) {
    const t = timeParts(m[4]);
    if (!t) return null;
    const year = m[3].length === 2 ? 2000 + Number(m[3]) : Number(m[3]);
    return build(year, Number(m[2]), Number(m[1]), ...t);
  }

  m = /^(\d{1,2})(?:st|nd|rd|th)?[ -]([A-Za-z]{3,9})\.?,?[ -](\d{4})(?: (.+))?$/.exec(text);
  if (m) {
    const month = MONTHS.indexOf(m[2].slice(0, 3).toLowerCase());
    const t = timeParts(m[4]);
    return month < 0 || !t ? null : build(Number(m[3]), month + 1, Number(m[1]), ...t);
  }

  m = /^([A-Za-z]{3,9})\.? (\d{1,2})(?:st|nd|rd|th)?,? (\d{4})(?: (.+))?$/.exec(text);
  if (m) {
    const month = MONTHS.indexOf(m[1].slice(0, 3).toLowerCase());
    const t = timeParts(m[4]);
    return month < 0 || !t ? null : build(Number(m[3]), month + 1, Number(m[2]), ...t);
  }
  return null;
}

/** Guesses the method from free text such as "Pay Bill", "Equity Bank" or "Cash deposit". */
export function guessPaymentMethod(raw) {
  const text = cleanText(typeof raw === 'string' ? raw : '').toLowerCase();
  if (!text) return null;
  if (/m-?pesa|paybill|pay bill|buy goods|\btill\b/.test(text)) return 'mpesa';
  if (/cheque|check/.test(text)) return 'cheque';
  if (/cash/.test(text)) return 'cash';
  if (/card|visa|mastercard/.test(text)) return 'card';
  if (/bank|eft|rtgs|swift|transfer|deposit/.test(text)) return 'bank';
  return null;
}

/** "qgh7 xyz123" becomes "QGH7 XYZ123": comparison is case- and spacing-insensitive. */
export function normaliseReference(raw) {
  if (typeof raw === 'number' && Number.isFinite(raw)) return String(Math.trunc(raw));
  return typeof raw === 'string' ? raw.replace(/\s+/g, ' ').trim().toUpperCase() : '';
}

export const isValidReference = (reference) => REFERENCE_RE.test(reference);

/** The same payment seen twice (a statement imported again) gives the same text. Minute precision. */
export function paymentFingerprint({ paidAt, amountMinor, payerPhone = '', payerName = '' }) {
  const when = paidAt instanceof Date ? paidAt.toISOString().slice(0, 16) : String(paidAt ?? '').slice(0, 16);
  const who = payerPhone || cleanText(payerName).toLowerCase();
  return `${when}|${amountMinor}|${who}`;
}

/**
 * Validates one payment, whether typed into the form or read from a spreadsheet row.
 * @returns {{ ok: boolean, value: object, errors: Record<string, string> }}
 */
export function validatePayment(input, { now = new Date() } = {}) {
  const src = input && typeof input === 'object' ? input : {};
  const errors = {};
  const value = {};

  const studentId = typeof src.studentId === 'string' ? src.studentId.trim() : '';
  if (studentId && (studentId.length > 128 || studentId.includes('/'))) errors.studentId = 'Choose a student from the list.';
  else value.studentId = studentId || null;

  let amountMinor = src.amountMinor;
  if (amountMinor === undefined && src.amount !== undefined) amountMinor = parseAmountMinor(src.amount);
  if (!Number.isInteger(amountMinor) || amountMinor < 1 || amountMinor > MAX_AMOUNT_MINOR) {
    errors.amount = 'Enter an amount greater than zero, like 15,000 or 1,500.50.';
  } else value.amountMinor = amountMinor;

  const paidAt = parsePaidAt(src.paidAt); // an ISO string with Z or an offset keeps its own time zone
  if (!paidAt || Number.isNaN(paidAt.getTime())) errors.paidAt = 'Enter the date the money was received.';
  else if (paidAt.getTime() < EARLIEST_PAYMENT) errors.paidAt = 'That date is too long ago. Check the year.';
  else if (paidAt.getTime() > now.getTime() + 24 * 3600 * 1000) errors.paidAt = 'The payment date cannot be in the future.';
  else value.paidAt = paidAt;

  if (!PAYMENT_METHODS.includes(src.method)) errors.method = 'Choose how the money was paid.';
  else value.method = src.method;

  const purpose = src.purpose == null || src.purpose === '' ? 'tuition' : src.purpose;
  if (!PAYMENT_PURPOSES.includes(purpose)) errors.purpose = 'Choose what the payment is for.';
  else value.purpose = purpose;

  const reference = normaliseReference(src.reference);
  if (reference && !isValidReference(reference)) errors.reference = 'The reference can use letters, numbers and . _ / # : - only (up to 60 characters).';
  else value.reference = reference;

  const payerName = cleanText(src.payerName);
  if (payerName.length > 80) errors.payerName = 'The payer name must be 80 characters or fewer.';
  else value.payerName = payerName;

  const rawPhone = cleanText(src.payerPhone);
  const phone = rawPhone ? normalisePhone(rawPhone) : '';
  if (rawPhone && !phone) errors.payerPhone = 'Enter a valid phone number, like 0712 345 678.';
  else value.payerPhone = phone || '';

  const note = cleanText(src.note);
  if (note.length > 300) errors.note = 'The note must be 300 characters or fewer.';
  else value.note = note;

  return { ok: Object.keys(errors).length === 0, value, errors };
}

/** Where a student stands against the fees agreed for them. */
export function balanceState(feeDueMinor, paidMinor) {
  if (!Number.isInteger(feeDueMinor) || feeDueMinor <= 0) return { key: 'none', label: paidMinor > 0 ? 'Paid, no fee set' : 'No fee set', balanceMinor: null };
  const balanceMinor = feeDueMinor - paidMinor;
  if (balanceMinor < 0) return { key: 'over', label: 'Overpaid', balanceMinor };
  if (balanceMinor === 0) return { key: 'cleared', label: 'Cleared', balanceMinor };
  return paidMinor > 0 ? { key: 'part', label: 'Part paid', balanceMinor } : { key: 'unpaid', label: 'Unpaid', balanceMinor };
}
